55	// What MHPCO insures each item for, as distinct from what it charges to do so.
56	const INSURANCE_VALUES: Record<string, number> = {
57	  sword: 1000,
58	  amulet: 600,
59	  staff: 800,
60	  potion: 400,
61	  rune: 250,
62	  moonstone: 250,
63	};
64	
65	const BASE_PREMIUMS: Record<string, number> = {
66	  sword: 100,
67	  amulet: 60,
68	  staff: 80,
69	  potion: 40,
70	  rune: 25,
71	  moonstone: 25,
72	};
73	
74	// Percentages are applied as integer arithmetic (× percent ÷ 100) rather than
75	// as a float rate (× 1.1): this keeps intermediate values integral and avoids
76	// binary floating-point error — 100 * 1.1 is 110.00000000000001, but
77	// (100 * 110) / 100 is exact.
78	const ONE_HUNDRED_PERCENT = 100;
79	const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
80	const ADMIN_FEE = 5;
81	const LOYALTY_YEARS = 2;
82	const LOYALTY_DISCOUNT_PERCENT = 20;
83	const SUBSEQUENT_CONTRACT_DISCOUNT_PERCENT = 15;
84	const DEDUCTIBLE = 100;
85	const CAP_MULTIPLE = 2;
86	const NO_PAYOUT = 0;
87	
88	const applyPercent = (amount: number, percent: number): number =>
89	  (amount * percent) / ONE_HUNDRED_PERCENT;
90	
91	const addSurcharge = (amount: number, surchargePercent: number): number =>
92	  applyPercent(amount, ONE_HUNDRED_PERCENT + surchargePercent);
93	
94	const applyDiscount = (amount: number, discountPercent: number): number =>
95	  applyPercent(amount, ONE_HUNDRED_PERCENT - discountPercent);
96	
97	const COMPONENT_TYPES = ["rune", "moonstone"];
98	const BUILDING_BLOCK_SIZE = 3;
99	const BUILDING_BLOCK_BASE_PREMIUM = 60;
100	const isComponent = (item: Item): boolean => COMPONENT_TYPES.includes(item.type);
101	
102	const basePremiumOf = (item: Item): number => BASE_PREMIUMS[item.type];
103	
104	// Risk surcharges are per-item properties of the insured object, each raising
105	// that item's premium by a percentage. They stack multiplicatively: an item
106	// matching two rules is surcharged by the first, then by the second.
107	interface RiskSurcharge {
108	  appliesTo: (item: Item) => boolean;
109	  percent: number;
110	}
111	
112	const HIGH_ENCHANTMENT = 5;
113	const NO_ENCHANTMENT = 0;
114	
115	const RISK_SURCHARGES: RiskSurcharge[] = [
116	  { appliesTo: (item) => item.cursed === true, percent: 50 },
117	  {
118	    appliesTo: (item) => (item.enchantment ?? NO_ENCHANTMENT) >= HIGH_ENCHANTMENT,
119	    percent: 30,
120	  },
121	];
122	
123	const riskAdjustedPremiumOf = (item: Item): number =>
124	  RISK_SURCHARGES.reduce(
125	    (premium, surcharge) =>
126	      surcharge.appliesTo(item) ? addSurcharge(premium, surcharge.percent) : premium,
127	    basePremiumOf(item),
128	  );
129	
130	const sumRiskAdjustedPremiums = (items: Item[]): number =>
131	  items.reduce((total, item) => total + riskAdjustedPremiumOf(item), 0);
132	
133	// Alike components are grouped into building blocks of 3, which carry a
134	// special base premium; the remaining components are priced individually,
135	// risk surcharges and all.
136	// Total over the empty group: no components means no blocks and no remainder.
137	const alikeComponentsPremium = (components: Item[]): number => {
138	  const blockCount = Math.floor(components.length / BUILDING_BLOCK_SIZE);
139	  const remainingComponents = components.slice(blockCount * BUILDING_BLOCK_SIZE);
140	  return (
141	    blockCount * BUILDING_BLOCK_BASE_PREMIUM +
142	    sumRiskAdjustedPremiums(remainingComponents)
143	  );
144	};
145	
146	// Splits items into those matching the predicate and those not, in one pass,
147	// so the rule dividing them is written exactly once.
148	const partition = (
149	  items: Item[],
150	  matches: (item: Item) => boolean,
151	): [Item[], Item[]] =>
152	  items.reduce<[Item[], Item[]]>(
153	    ([matching, rest], item) =>
154	      matches(item) ? [[...matching, item], rest] : [matching, [...rest, item]],
155	    [[], []],
156	  );
157	
158	const groupByType = (items: Item[]): Item[][] => [
159	  ...items
160	    .reduce(
161	      (groups, item) =>
162	        groups.set(item.type, [...(groups.get(item.type) ?? []), item]),
163	      new Map<string, Item[]>(),
164	    )
165	    .values(),
166	];
167	
168	// Components and main items are priced by different rules, so each group is
169	// totalled separately: components by building block, main items item by item.
170	const componentsPremium = (components: Item[]): number =>
171	  groupByType(components).reduce(
172	    (total, alike) => total + alikeComponentsPremium(alike),
173	    0,
174	  );
175	
176	// What the items alone cost to insure, before any modifier that depends on the
177	// customer or the contract they sit in. This is a premium, not a sum insured:
178	// what MHPCO *charges* for the cover, not what it will *pay out* — an amulet
179	// costs 60 here and is insured for 600 (see insuranceSumOf). Every item is
180	// either a component or a main item — the split is stated once, as a partition,
181	// so the two halves cannot drift apart — and each half is priced by its own
182	// rules.
183	const itemsPremiumOf = (items: Item[]): number => {
184	  const [components, mainItems] = partition(items, isComponent);
185	  return sumRiskAdjustedPremiums(mainItems) + componentsPremium(components);
186	};
187	
188	// Contract-level modifiers adjust the sum insured by the terms of the deal
189	// rather than the nature of the items. Like risk surcharges they stack
190	// multiplicatively, each applying to the result of the one before, so they are
191	// written the same way: a predicate over the contract, and an adjustment.
192	interface Contract {
193	  customer: Customer;
194	  isFirstContract: boolean;
195	}
196	
197	interface ContractModifier {
198	  appliesTo: (contract: Contract) => boolean;
199	  adjust: (amount: number) => number;
200	}
201	
202	// Every contract is priced on one of two standings: a first insurance is
203	// assessed a surcharge, a later one rewarded with a discount. This is a choice,
204	// not two independent rules, so it is written as one — there is no way to
205	// express a contract that gets both or neither.
206	const standingAdjustedPremiumOf = (
207	  amount: number,
208	  { isFirstContract }: Contract,
209	): number =>
210	  isFirstContract
211	    ? addSurcharge(amount, FIRST_INSURANCE_SURCHARGE_PERCENT)
212	    : applyDiscount(amount, SUBSEQUENT_CONTRACT_DISCOUNT_PERCENT);
213	
214	// Modifiers that a contract may or may not earn, on top of its standing. They
215	// stack multiplicatively, each applying to the result of the one before.
216	const CONTRACT_MODIFIERS: ContractModifier[] = [
217	  {
218	    appliesTo: ({ customer }) => customer.yearsWithMHPCO >= LOYALTY_YEARS,
219	    adjust: (amount) => applyDiscount(amount, LOYALTY_DISCOUNT_PERCENT),
220	  },
221	];
222	
223	const contractAdjustedPremiumOf = (
224	  itemsPremium: number,
225	  contract: Contract,
226	): number =>
227	  CONTRACT_MODIFIERS.reduce(
228	    (premium, modifier) =>
229	      modifier.appliesTo(contract) ? modifier.adjust(premium) : premium,
230	    standingAdjustedPremiumOf(itemsPremium, contract),
231	  );
232	
233	// Premiums round up in MHPCO's favour, and the flat admin fee is added last
234	// so that no percentage ever applies to it.
235	const billedPremiumOf = (premium: number): number =>
236	  Math.ceil(premium) + ADMIN_FEE;
237	
238	const quote = (step: QuoteStep, contract: Contract): QuoteResult => ({
239	  premium: billedPremiumOf(
240	    contractAdjustedPremiumOf(itemsPremiumOf(step.items), contract),
241	  ),
242	});
243	
244	// The insurance sum is what the items are covered for, and it is the basis of
245	// the payout cap — unrelated to the premium charged for that cover.
246	const insuranceSumOf = (items: Item[]): number =>
247	  items.reduce((total, item) => total + INSURANCE_VALUES[item.type], 0);
248	
249	// A quote creates a policy, which then absorbs claims: every payout draws down
250	// a cap of twice the insurance sum, so the policy carries state between steps.
251	interface Policy {
252	  remainingCap: number;
253	}
254	
255	const policyFor = (items: Item[]): Policy => ({
256	  remainingCap: insuranceSumOf(items) * CAP_MULTIPLE,
257	});
258	
259	const claim = (step: ClaimStep, policy: Policy): ClaimResult => {
260	  const damageTotal = step.incident.damages.reduce(
261	    (total, damage) => total + damage.amount,
262	    0,
263	  );
264	  // The deductible reduces the payout, it never turns it into a charge.
265	  const payout = Math.max(damageTotal - DEDUCTIBLE, NO_PAYOUT);
266	  return { payout, remainingCap: policy.remainingCap - payout };
267	};
268	
269	// Steps are processed in order because each one depends on what came before: a
270	// quote's standing depends on how many contracts precede it, and a claim draws
271	// down the cap its policy has left. Both are carried explicitly as the policies
272	// map rather than mutated in place, so a step's effect on later steps is
273	// visible in what it returns.
274	interface Ledger {
275	  policies: Map<number, Policy>;
276	  results: StepResult[];
277	}
278	
279	const withPolicy = (
280	  policies: Map<number, Policy>,
281	  index: number,
282	  policy: Policy,
283	): Map<number, Policy> => new Map(policies).set(index, policy);
284	
285	const applyStep = (
286	  { policies, results }: Ledger,
287	  step: Step,
288	  index: number,
289	  customer: Customer,
290	): Ledger => {
291	  if (step.op === "quote") {
292	    const contract = { customer, isFirstContract: index === 0 };
293	    return {
294	      policies: withPolicy(policies, index, policyFor(step.items)),
295	      results: [...results, quote(step, contract)],
296	    };
297	  }
298	  const policy = policies.get(step.policy);
299	  if (policy === undefined) {
300	    throw new Error(`Claim refers to unknown policy ${step.policy}`);
301	  }
302	  const result = claim(step, policy);
303	  return {
304	    policies: withPolicy(policies, step.policy, {
305	      remainingCap: result.remainingCap,
306	    }),
307	    results: [...results, result],
308	  };
309	};
310	
311	export const runScenario = ({ customer, steps }: Scenario): ScenarioResult => {
312	  const { results } = steps.reduce<Ledger>(
313	    (ledger, step, index) => applyStep(ledger, step, index, customer),
314	    { policies: new Map(), results: [] },
315	  );
316	  return { results };
317	};
