// An incident's damages are totalled before the deductible is taken, so the
// deductible falls once on the event rather than once per damaged item.
const damageTotalOf = (incident: Incident): number =>
  incident.damages.reduce((total, damage) => total + damage.amount, 0);

const claim = (step: ClaimStep, policy: Policy): ClaimResult => {
  // The deductible reduces the payout, it never turns it into a charge.
  const payout = Math.max(damageTotalOf(step.incident) - DEDUCTIBLE, NO_PAYOUT);
  return { payout, remainingCap: policy.remainingCap - payout };
};
